css:
.dcx{scroll-padding-top:112px;scroll-behavior:smooth}
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#17211D;-webkit-font-smoothing:antialiased;}
.dcx *{box-sizing:border-box}
.dcx h1,.dcx h2,.dcx h3,.dcx h4,.dcx p,.dcx figure{margin:0}
.dcx a{color:#0C4B3B;text-decoration:none}
.dcx a:hover{color:#08362A}
.dcx *:focus-visible{outline:2px solid #FF6347;outline-offset:3px}
.dcx ::selection{background:#FFE1DA}
.dcx .nx-arr{display:inline-flex;transition:transform .16s ease-out}
.dcx .nx-cta:hover .nx-arr{transform:translateX(3px)}
.dcx .nx-btn{transition:transform .16s ease-out,box-shadow .16s ease-out,background .16s}
.dcx .nx-btn:hover{transform:translateY(-1px);box-shadow:0 10px 22px -12px rgba(0,0,0,.35)}
.dcx details.nxb-faq summary::-webkit-details-marker,.dcx details.nxb-mtoc summary::-webkit-details-marker{display:none}
.dcx details.nxb-faq[open] .nxb-plus{transform:rotate(45deg)}
.dcx .nxb-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:56px;justify-content:center}
.dcx .nxb-side{display:none}
.dcx .nxm{container-type:inline-size}
@container (max-width:640px){.dcx .nxm-side{display:none !important}
}
@container (max-width:440px){.dcx .nxm-hide{display:none !important}
}
@media (min-width:1100px){.dcx .nxb-grid{grid-template-columns:232px minmax(0,740px)}
.dcx .nxb-side{display:block}
.dcx .nxb-mtoc{display:none}
}
@media (prefers-reduced-motion: reduce){.dcx *{transition-duration:.01ms !important;scroll-behavior:auto !important}
.dcx .nx-btn:hover{transform:none}
}

